steps.command:
perl -e 'my $pid = fork();
if ($pid == 0) { sleep 30; exit 0 }
sleep 1;
syscall(117, 16, $pid, 0, 0) == 0 or die "ATTACH 실패: $!\n";
waitpid($pid, 0);
open(my $mp, "<", "/proc/$pid/maps") or die;
my $addr = hex((split /-/, <$mp>)[0]);
syscall(117, 5, $pid, $addr, 0);
syscall(117, 17, $pid, 0, 0);
kill 9, $pid;
print "ptrace 주입 완료\n";'
